def f(g, maxgap=2):
    cnt=Counter(x for row in g for x in row); bg=cnt.most_common(1)[0][0]
    pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v!=bg]
    r0=min(r for r,_ in pts); r1=max(r for r,_ in pts); c0=min(c for _,c in pts); c1=max(c for _,c in pts)
    out=[row[:] for row in g]
    # border fill
    for rr in range(r0,r1+1):
        for cc in (c0,c1):
            if out[rr][cc]==bg: out[rr][cc]=2
    for cc in range(c0,c1+1):
        for rr in (r0,r1):
            if out[rr][cc]==bg: out[rr][cc]=2
    # gap fill rows and cols
    H,W=len(g),len(g[0])
    for rr in range(H):
        rs=sorted({c for c,v in enumerate(g[rr]) if v!=bg})
        for a,b in zip(rs,rs[1:]):
            if b-a<=maxgap:
                for c in range(a+1,b):
                    if out[rr][c]==bg: out[rr][c]=2
    for cc in range(W):
        vs=sorted({r for r in range(H) if g[r][cc]!=bg})
        for a,b in zip(vs,vs[1:]):
            if b-a<=maxgap:
                for r in range(a+1,b):
                    if out[r][cc]==bg: out[r][cc]=2
    return out
