    cnt=Counter(x for row in g for x in row); bgv=max(cnt,key=cnt.get)
    seen=[[False]*W for _ in range(H)]; q=deque()
    for r in range(H):
        for c in (0,W-1):
            if g[r][c]==bgv and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if g[r][c]==bgv and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    while q:
        y,x=q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and g[ny][nx]==bgv and not seen[ny][nx]:
                seen[ny][nx]=True; q.append((ny,nx))
    return [[2 if g[r][c]==bgv and not seen[r][c] else g[r][c] for c in range(W)] for r in range(H)]
for n in [1,2]:
    i=G[f'Demo pair {n} input']; oo=G[f'Demo pair {n} output']
    p=f(i)
    d=[(r,c,p[r][c],oo[r][c]) for r in range(len(oo)) for c in range(len(oo[0])) if p[r][c]!=oo[r][c]]
    print(n,p==oo,d[:12],'...' if len(d)>12 else '')
